const returnVaultPlansForVaultBranch = `-- name: ReturnVaultPlansForVaultBranch :many
UPDATE vendor_request_vault_plans p
SET status = 'draft', approved_by = NULL, approved_at = NULL,
    rejected_by = $1::bigint, rejected_at = now(), rejection_reason = $2::text
WHERE p.vendor_request_id = $3::bigint AND p.status <> 'cancelled'
  AND p.id IN (SELECT a.vault_plan_id FROM vendor_request_vault_assignments a
               WHERE a.vendor_request_id = $3::bigint AND a.vault_branch_id = $4::bigint)
RETURNING p.id, p.acm_area_id
`

type ReturnVaultPlansForVaultBranchParams struct {
	ActorID       int64  `json:"actor_id"`
	Reason        string `json:"reason"`
	RequestID     int64  `json:"request_id"`
	VaultBranchID int64  `json:"vault_branch_id"`
}

type ReturnVaultPlansForVaultBranchRow struct {
	ID        int64 `json:"id"`
	AcmAreaID int64 `json:"acm_area_id"`
}

// FR4.3: branch vault menolak -> hanya plan area yang memuat ATM dengan vault itu kembali draft; alasan vendor
// tercatat sebagai penolakan plan (rejected_by = user vendor, dipakai UI untuk label "Ditolak vendor").
func (q *Queries) ReturnVaultPlansForVaultBranch(ctx context.Context, arg ReturnVaultPlansForVaultBranchParams) ([]ReturnVaultPlansForVaultBranchRow, error) {
	rows, err := q.db.Query(ctx, returnVaultPlansForVaultBranch,
		arg.ActorID,
		arg.Reason,
		arg.RequestID,
		arg.VaultBranchID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReturnVaultPlansForVaultBranchRow{}
	for rows.Next() {
		var i ReturnVaultPlansForVaultBranchRow
		if err := rows.Scan(&i.ID, &i.AcmAreaID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const withdrawVendorParty = `-- name: WithdrawVendorParty :one
UPDATE vendor_request_vendor_parties
SET status = 'withdrawn', decided_by = NULL, decided_at = NULL, rejection_reason = NULL
WHERE id = $1
RETURNING id, vendor_request_id, vendor_branch_id, role, status, content, sent_at, decided_by, decided_at, rejection_reason, created_at, updated_at
`

func (q *Queries) WithdrawVendorParty(ctx context.Context, id int64) (VendorRequestVendorParty, error) {
	row := q.db.QueryRow(ctx, withdrawVendorParty, id)
	var i VendorRequestVendorParty
	err := row.Scan(
		&i.ID,
		&i.VendorRequestID,
		&i.VendorBranchID,
		&i.Role,
		&i.Status,
		&i.Content,
		&i.SentAt,
		&i.DecidedBy,
		&i.DecidedAt,
		&i.RejectionReason,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
